from ._tulis import Q, bab, kursus, latihan

# ---------------------------------------------------------------- 6 Data Analyst
# Semua fakta SQL diambil dari dokumentasi SQLite (fungsi agregat) dan artikel KDnuggets yang tercantum di `sumber`.
kursus(6, "Data Analyst",
 bab(["Menjelaskan alur kerja dasar analis data: ambil data, saring, ringkas, dan laporkan.",
      "Menyebut enam jenis query SQL yang dibahas artikel KDnuggets untuk analis data.",
      "Menjelaskan mengapa angka hasil query harus bisa diperiksa orang lain.",
      "Menyiapkan data latihan kecil yang aman dipakai di komputer sendiri."],
  ("Alur kerja analis data",
   "Artikel KDnuggets berjudul SQL for Data Analysts: Essential Queries for Data Extraction and Transformation membahas 15 query SQL dasar untuk analis data. Judulnya sudah menunjukkan dua pekerjaan utama: mengambil data (extraction) dan mengubah bentuk data (transformation). Dalam kursus ini alurnya disederhanakan menjadi empat langkah: ambil data dengan SELECT, saring baris dengan WHERE, ringkas dengan GROUP BY dan fungsi agregat, lalu laporkan hasilnya dengan kalimat yang bisa dipahami orang yang tidak membaca query-nya."),
  ("Enam query yang dipelajari",
   "Dari artikel itu kursus ini memakai enam: SELECT untuk memilih kolom, WHERE untuk memfilter baris, GROUP BY untuk mengelompokkan dan meringkas, JOIN untuk menggabungkan dua tabel lewat kolom yang berelasi, CASE untuk membuat kolom kondisional seperti if-else, dan window function untuk menghitung lintas baris tanpa menggabungkan barisnya. Fungsi agregat dan perilaku NULL diambil dari dokumentasi SQLite, karena hasil hitungan yang tampak benar bisa salah bila NULL tidak dipahami."),
  ("Menyiapkan latihan dan menjaga angka tetap bisa diperiksa",
   "Semua latihan memakai SQLite karena gratis, ringan, dan jalan di komputer sendiri; buat tabel kecil berisi data rekaan seperti employees dan departments, jangan memakai data pribadi siswa atau pelanggan sungguhan. Untuk setiap angka yang kamu laporkan, simpan query-nya, tanggal menjalankannya, dan jumlah baris yang dipakai. Dengan begitu temanmu bisa menjalankan ulang dan mendapat angka yang sama. Bila angkanya berbeda, cari tahu dulu penyebabnya sebelum melapor, misalnya data yang berubah atau NULL yang tidak ikut terhitung.")),
 bab(["Menulis SELECT yang memilih kolom tertentu dan menjelaskan arti tanda bintang.",
      "Menulis WHERE untuk menyaring baris berdasarkan satu kondisi.",
      "Menulis GROUP BY dengan AVG, SUM, atau COUNT untuk meringkas per kelompok.",
      "Menjelaskan beda WHERE dan HAVING."],
  ("SELECT dan WHERE",
   "Menurut KDnuggets, SELECT name, age, salary FROM employees mengambil kolom tertentu dari tabel, sedangkan tanda bintang mengembalikan semua kolom. WHERE menyaring baris: SELECT * FROM employees WHERE department = 'Finance' hanya mengembalikan baris yang memenuhi kondisi itu. Kebiasaan baik: sebutkan kolom yang dibutuhkan saja, supaya hasil lebih mudah dibaca dan diperiksa."),
  ("GROUP BY dan HAVING",
   "GROUP BY mengelompokkan baris yang bernilai sama pada satu kolom lalu menghitung agregat untuk tiap kelompok. Contoh KDnuggets: SELECT department, AVG(salary) AS avg_salary FROM employees GROUP BY department. HAVING dipakai untuk memfilter setelah agregasi dilakukan, misalnya HAVING COUNT(*) > 10 untuk menampilkan departemen yang punya lebih dari 10 karyawan. WHERE bekerja pada baris sebelum pengelompokan, HAVING bekerja pada hasil kelompok.")),
 bab(["Menggabungkan dua tabel dengan JOIN dan menunjuk kolom penghubungnya.",
      "Memakai alias tabel dan alias kolom agar query mudah dibaca.",
      "Membuat kolom kategori dengan CASE.",
      "Mengenali kesalahan umum pada JOIN, yaitu salah kolom penghubung."],
  ("JOIN",
   "JOIN menggabungkan baris dari dua tabel berdasarkan kolom yang berelasi. Contoh dari KDnuggets: SELECT e.name, d.name AS department FROM employees e JOIN departments d ON e.dept_id = d.id. Huruf e dan d adalah alias tabel, dan AS department memberi nama baru untuk kolom hasil. Bagian ON menentukan kolom penghubung; bila salah memilih kolom, hasilnya bisa berupa pasangan data yang tidak masuk akal."),
  ("CASE",
   "CASE bekerja seperti logika if-else di dalam query. Contoh KDnuggets mengelompokkan umur: WHEN age < 30 THEN 'Junior', WHEN age BETWEEN 30 AND 50 THEN 'Mid-level', ELSE 'Senior', lalu hasilnya diberi nama experience_level. Analis memakai CASE untuk mengubah angka menjadi kategori yang mudah dilaporkan, tetapi batas kategorinya harus ditulis di laporan agar pembaca tahu cara menilainya.")),
 bab(["Membedakan count(*) dan count(X) pada data yang berisi NULL.",
      "Menjelaskan beda sum() dan total() menurut dokumentasi SQLite.",
      "Menjelaskan jenis hasil avg() dan perlakuannya terhadap NULL.",
      "Memakai DISTINCT, FILTER, dan group_concat dengan benar."],
  ("count, sum, total, avg",
   "Dokumentasi SQLite menjelaskan bahwa count(*) menghitung seluruh baris dalam grup, sedangkan count(X) hanya menghitung baris yang nilai X-nya bukan NULL. Bila kolom X berisi 1, NULL, 3, maka count(*) bernilai 3 dan count(X) bernilai 2. Bila tidak ada input non-NULL, sum() mengembalikan NULL sedangkan total() mengembalikan 0.0, dan total() selalu mengembalikan angka pecahan. avg() mengembalikan rata-rata nilai non-NULL dan hasilnya selalu angka pecahan; dari 1 dan 2 hasilnya 1.5. min() dan max() juga mengabaikan NULL."),
  ("DISTINCT, FILTER, group_concat",
   "Pada fungsi agregat satu argumen, DISTINCT diletakkan sebelum argumen: count(distinct X) menghitung nilai unik X. Klausa FILTER (WHERE expr) membatasi agregasi hanya pada baris yang memenuhi ekspresi itu. group_concat(X, Y) menggabungkan semua nilai X yang bukan NULL dengan pemisah Y, dan bila Y tidak diberikan pemisahnya koma. Urutan hasilnya bebas kecuali ada ORDER BY di dalam fungsi tersebut.")),
 bab(["Memakai window function untuk membuat peringkat tanpa menggabungkan baris.",
      "Menyusun satu analisis kecil dari pertanyaan sampai kesimpulan.",
      "Menulis kesimpulan yang menyebut batas data.",
      "Mengenali kapan hasil query perlu dicek ulang."],
  ("Window function",
   "Window function menghitung nilai lintas baris tanpa menggabungkan baris menjadi satu, sehingga detail tiap baris tetap tampil. Contoh KDnuggets: SELECT name, salary, RANK() OVER (ORDER BY salary DESC) AS salary_rank FROM employees. Artikel menyebut fungsi ini umum dipakai untuk ranking, running total, dan perbandingan antarbaris. Beda dengan GROUP BY yang mengurangi jumlah baris, di sini setiap karyawan tetap muncul dengan peringkatnya."),
  ("Dari pertanyaan ke kesimpulan",
   "Mulai dari pertanyaan yang jelas, misalnya departemen mana yang rata-rata gajinya tertinggi. Tulis query dengan GROUP BY dan AVG, periksa dengan count(*) berapa baris yang masuk tiap kelompok, lalu cek apakah ada NULL yang membuat rata-rata tidak mewakili semua baris. Kesimpulan yang jujur menyebut jumlah baris, tanggal data, dan keterbatasannya, misalnya data hanya 20 karyawan rekaan. Bila hasil terasa aneh, jalankan versi yang lebih sederhana dulu sebelum menambah JOIN atau CASE.")),
 {"title": "Analisis data kecil dengan SQL",
  "brief": "Buat database SQLite berisi dua atau tiga tabel rekaan, misalnya karyawan, departemen, dan penjualan, dengan minimal 30 baris dan beberapa nilai NULL yang sengaja kamu sisipkan. Tulis lima pertanyaan bisnis dan jawab masing-masing dengan query SQL. Pakai SELECT, WHERE, GROUP BY dengan HAVING, JOIN, CASE, dan satu window function. Tulis laporan satu halaman yang berisi pertanyaan, query, hasil, kesimpulan, dan batas datanya.",
  "criteria": ["Database berisi minimal 30 baris dan skema tabel dijelaskan.",
               "Lima pertanyaan bisnis ditulis jelas dan tiap pertanyaan dijawab oleh satu query.",
               "Penggunaan JOIN benar, dengan penjelasan kolom penghubung.",
               "Ada GROUP BY dengan HAVING dan penjelasan beda WHERE dan HAVING.",
               "Ada CASE yang membuat kategori, dengan batas kategori disebut di laporan.",
               "Ada satu window function dan penjelasan bedanya dengan GROUP BY.",
               "Perilaku NULL dibahas: minimal satu kasus count(*) berbeda dengan count(X) diperlihatkan.",
               "Setiap kesimpulan menyebut jumlah baris dan keterbatasan data."]},
 [
 Q(2, "A", "Menurut KDnuggets, SELECT dipakai untuk:", "Memilih kolom dari tabel", "Menghapus seluruh tabel beserta data di dalamnya dari database", "Mengurutkan isi kolom berdasarkan urutan huruf dalam abjad", "Menggambar grafik batang dari hasil perhitungan angka secara otomatis", "a", "Contohnya SELECT name, age, salary FROM employees mengambil kolom tertentu."),
 Q(2, "A", "Tanda bintang pada SELECT * berarti:", "Semua kolom", "Kolom pertama saja", "Kolom angka saja", "Tidak ada kolom", "a", "KDnuggets menyebut tanda bintang mengembalikan semua kolom."),
 Q(2, "K", "Klausa yang menyaring baris sebelum dikelompokkan adalah:", "WHERE", "HAVING", "GROUP BY", "CASE", "a", "WHERE menyaring baris; HAVING dipakai setelah agregasi."),
 Q(2, "K", "Untuk menampilkan departemen yang punya lebih dari 10 karyawan, kamu memakai:", "GROUP BY department HAVING COUNT(*) > 10", "WHERE COUNT(*) > 10 tanpa GROUP BY pada kolom department", "ORDER BY department > 10 pada akhir query yang dibuat", "CASE WHEN department > 10 pada bagian SELECT query itu", "a", "Contoh KDnuggets memakai HAVING COUNT(*) > 10 setelah GROUP BY."),
 Q(2, "K", "SELECT department, AVG(salary) FROM employees GROUP BY department menghasilkan:", "Satu rata-rata gaji untuk tiap departemen", "Satu rata-rata gaji untuk seluruh perusahaan", "Gaji tiap karyawan", "Daftar departemen tanpa angka", "a", "GROUP BY menghitung agregat untuk tiap kelompok."),
 Q(2, "K", "Perbedaan WHERE dan HAVING yang benar:", "WHERE bekerja pada baris sebelum pengelompokan, HAVING pada hasil kelompok", "HAVING selalu dijalankan sebelum WHERE pada setiap query yang memakai keduanya", "Keduanya selalu dapat saling menggantikan tanpa mengubah hasil query sama sekali", "WHERE hanya dipakai untuk kolom teks dan HAVING hanya untuk kolom angka", "a", "KDnuggets: HAVING dipakai untuk memfilter setelah agregasi dilakukan."),
 Q(2, "A", "AS avg_salary pada query berfungsi untuk:", "Memberi nama baru pada kolom hasil", "Menghapus kolom yang tidak dipakai dari tabel sumber data", "Mengunci tabel supaya tidak dapat dibaca oleh pengguna lain", "Menyaring baris yang nilainya lebih besar dari rata-rata gaji", "a", "AS memberi alias pada kolom hasil."),
 Q(3, "A", "JOIN dipakai untuk:", "Menggabungkan baris dari dua tabel lewat kolom yang berelasi", "Menghapus baris ganda yang terdapat di dalam satu tabel", "Mengubah nama tabel supaya mudah diingat oleh pengguna lain", "Mengecilkan ukuran berkas database agar hemat ruang penyimpanan", "a", "KDnuggets: JOIN menggabungkan baris dari dua tabel berdasarkan kolom yang berelasi."),
 Q(3, "K", "Pada ON e.dept_id = d.id, bagian ON menentukan:", "Kolom penghubung antara dua tabel", "Urutan baris yang ditampilkan pada hasil query tersebut", "Jumlah baris maksimum yang boleh muncul pada hasil akhir", "Nama berkas database yang akan dibuka oleh query tersebut", "a", "ON berisi kondisi penghubung antar tabel."),
 Q(3, "K", "Pada contoh KDnuggets, huruf e dan d adalah:", "Alias tabel employees dan departments", "Nama kolom wajib yang harus ada pada setiap tabel SQL", "Tipe data angka yang dipakai untuk kolom penghubung tabel", "Kata kunci SQL yang menggantikan perintah JOIN dalam query", "a", "FROM employees e JOIN departments d memberi alias e dan d."),
 Q(3, "K", "Bila kolom penghubung JOIN salah dipilih, kemungkinan hasilnya:", "Pasangan data yang tidak masuk akal", "Query otomatis diperbaiki oleh SQLite sehingga hasil tetap tepat", "Database dihapus oleh SQLite karena kolom penghubung tidak cocok", "Hasil selalu kosong karena SQLite menolak semua kolom penghubung", "a", "Kolom penghubung yang salah menghasilkan pasangan data yang keliru, sehingga hasil harus diperiksa."),
 Q(3, "A", "CASE pada SQL berfungsi seperti:", "Logika if-else di dalam query", "Perulangan for yang mengulang perintah untuk setiap baris", "Perintah untuk menyalin berkas database ke folder lain", "Perintah untuk menghapus kolom dari tabel secara permanen", "a", "KDnuggets menyebut CASE sebagai logika kondisional."),
 Q(3, "K", "Pada contoh CASE KDnuggets, umur 25 masuk kategori:", "Junior", "Mid-level", "Senior", "Tidak masuk kategori", "a", "WHEN age < 30 THEN 'Junior'."),
 Q(3, "K", "Mengapa batas kategori CASE perlu ditulis di laporan?", "Agar pembaca tahu cara kategori dinilai", "Agar laporan terlihat lebih panjang dan tampak lebih lengkap", "Karena SQL mewajibkan batas kategori ditulis di dalam laporan", "Agar query berjalan lebih cepat pada tabel dengan banyak baris", "a", "Batas kategori memengaruhi arti hasil, jadi pembaca perlu mengetahuinya."),
 Q(4, "K", "Kolom X berisi 1, NULL, 3. Nilai count(*) adalah:", "3", "2", "1", "0", "a", "Dokumentasi SQLite: count(*) menghitung semua baris termasuk yang berisi NULL."),
 Q(4, "K", "Kolom X berisi 1, NULL, 3. Nilai count(X) adalah:", "2", "3", "1", "NULL", "a", "count(X) hanya menghitung baris yang nilai X bukan NULL."),
 Q(4, "K", "Jika tidak ada input non-NULL, sum() mengembalikan:", "NULL", "0.0", "0 bulat", "Error selalu", "a", "Dokumentasi SQLite: sum() mengembalikan NULL, sedangkan total() mengembalikan 0.0."),
 Q(4, "K", "avg() dari nilai 1 dan 2 menghasilkan:", "1.5", "1.0 karena avg() membulatkan hasil ke bilangan bulat terdekat", "2.0 karena avg() mengambil nilai terbesar dari kedua angka itu", "3.0 karena avg() menjumlahkan kedua angka tanpa membaginya", "a", "Dokumentasi SQLite menyebut avg() selalu mengembalikan angka pecahan; contohnya 1 dan 2 menghasilkan 1.5."),
 Q(4, "K", "total() berbeda dari sum() karena total():", "Selalu mengembalikan angka pecahan dan tidak melempar error integer overflow", "Hanya dapat dipakai pada kolom teks dan tidak pada kolom angka", "Selalu mengembalikan NULL ketika kolomnya memuat nilai yang kosong", "Ikut menghitung baris NULL sebagai angka satu pada setiap baris", "a", "Dokumentasi SQLite menyebut total() selalu floating point dan tidak pernah melempar error integer overflow."),
 Q(4, "A", "count(distinct X) menghitung:", "Jumlah nilai unik X", "Jumlah baris termasuk NULL", "Jumlah kolom", "Jumlah tabel", "a", "DISTINCT pada fungsi agregat menghitung nilai unik."),
 Q(4, "K", "Klausa FILTER (WHERE expr) pada fungsi agregat berfungsi untuk:", "Membatasi agregasi hanya pada baris yang memenuhi ekspresi", "Menghapus baris yang tidak memenuhi ekspresi dari tabel sumber", "Mengurutkan hasil agregasi dari nilai terbesar ke terkecil", "Menggabungkan dua tabel sebelum agregasi dihitung oleh SQLite", "a", "Dokumentasi SQLite: FILTER membatasi agregasi pada baris yang memenuhi expr."),
 Q(5, "A", "Window function RANK() OVER (ORDER BY salary DESC) menghasilkan:", "Peringkat gaji untuk tiap baris", "Satu baris saja yang berisi gaji paling tinggi di tabel", "Rata-rata gaji seluruh karyawan yang ditampilkan di tiap baris", "Daftar nama tabel yang memuat kolom gaji dalam database itu", "a", "Contoh KDnuggets membuat salary_rank tanpa menggabungkan baris."),
 Q(5, "K", "Perbedaan window function dan GROUP BY:", "Window function mempertahankan detail tiap baris, GROUP BY mengurangi jumlah baris", "Window function selalu lebih lambat daripada GROUP BY pada semua data", "GROUP BY mempertahankan semua baris asli sedangkan window function menggabungkannya", "Keduanya tidak dapat dipakai bersama fungsi agregat dalam satu query", "a", "KDnuggets: window function menghitung lintas baris tanpa menggabungkan baris menjadi satu."),
 Q(5, "K", "Sebelum menyimpulkan rata-rata per departemen, langkah pemeriksaan yang masuk akal:", "Cek jumlah baris tiap kelompok dan keberadaan NULL", "Langsung kirim hasilnya ke atasan agar cepat dibahas bersama", "Hapus semua baris NULL tanpa mencatat berapa baris yang hilang", "Ganti rata-rata dengan angka perkiraan yang terdengar masuk akal", "a", "NULL diabaikan oleh avg(), jadi jumlah baris tiap kelompok perlu dicek."),
 Q(5, "K", "Kesimpulan analisis yang jujur sebaiknya menyebut:", "Jumlah baris, tanggal data, dan keterbatasan data", "Hanya angka paling besar supaya laporan tampak meyakinkan", "Hanya kata sukses tanpa menjelaskan cara menghitungnya", "Tidak ada keterangan tambahan karena angka sudah cukup jelas", "a", "Agar pembaca dapat menilai seberapa jauh angka itu dapat dipercaya."),
 Q(5, "K", "Hasil query terasa aneh setelah menambah JOIN dan CASE. Langkah paling masuk akal:", "Jalankan versi yang lebih sederhana dulu lalu tambah bagian satu per satu", "Abaikan keanehan itu karena query sudah ditulis dengan benar", "Hapus tabel lalu buat ulang tanpa mencatat apa yang berubah", "Ganti semua angka dengan perkiraan agar laporan tetap selesai", "a", "Menambah bagian satu per satu membantu menemukan sumber kesalahan."),
 Q(5, "A", "Mengapa data latihan memakai data rekaan?", "Agar tidak membuka data pribadi orang sungguhan", "Karena data sungguhan tidak dapat dibaca oleh program SQLite", "Karena SQLite hanya menerima data rekaan pada tabel latihan", "Karena data rekaan selalu lebih akurat daripada data sungguhan", "a", "Latihan sebaiknya tidak memakai data pribadi siswa atau pelanggan."),
 Q(5, "K", "Sebuah laporan menyebut rata-rata gaji departemen Finance, tetapi dua dari sepuluh baris gajinya NULL. Pernyataan yang tepat:", "avg() menghitung dari delapan baris yang bukan NULL, jadi jumlah baris perlu disebut", "avg() menghitung sepuluh baris dengan NULL dianggap nol", "avg() otomatis mengisi NULL dengan rata-rata departemen lain", "avg() menolak data yang memuat NULL dan mengembalikan error", "a", "Dokumentasi SQLite: avg() mengembalikan rata-rata nilai non-NULL, sehingga baris NULL tidak ikut dihitung."),
 ],
 sumber=[("SQLite: Built-in Aggregate Functions", "https://sqlite.org/lang_aggfunc.html"),
         ("KDnuggets: SQL for Data Analysts, Essential Queries for Data Extraction and Transformation", "https://www.kdnuggets.com/sql-for-data-analysts-essential-queries-for-data-extraction-transformation")])
latihan(6,
 ["Tulis ulang empat langkah alur kerja analis data dengan kata-katamu dan beri satu contoh pertanyaan untuk tiap langkah.",
  "Pasang SQLite, buat tabel employees berisi 10 baris rekaan, lalu jalankan SELECT * dan SELECT dua kolom saja.",
  "Tulis tiga query WHERE dengan kondisi berbeda dan catat jumlah baris hasilnya."],
 ["Buat tabel departments dan jalankan JOIN dengan employees sampai muncul nama departemen tiap karyawan.",
  "Tulis query CASE yang mengelompokkan umur menjadi tiga kategori dan catat batasnya.",
  "Sengaja gunakan kolom penghubung yang salah pada satu JOIN, lalu tulis apa yang terjadi pada hasilnya."],
 ["Buat kolom yang berisi NULL, lalu bandingkan count(*) dan count(kolom).",
  "Jalankan sum() dan total() pada kolom yang seluruh barisnya NULL, dan catat perbedaannya.",
  "Hitung avg() pada kolom dengan NULL, lalu hitung manual dari nilai yang bukan NULL untuk memastikan hasilnya sama."],
 ["Tulis query RANK() untuk gaji karyawan dan bandingkan hasilnya dengan GROUP BY.",
  "Pilih satu pertanyaan, tulis query, hasil, dan kesimpulan satu paragraf dengan jumlah baris dan batas data.",
  "Minta temanmu menjalankan queries-mu di komputernya dan catat apakah angkanya sama."])
